NAME = 'ACV: A Conservative Version'
BOOK = 'Nehemiah'

CHAPTERS = {
    1: {
        1: 'Zgodbe Nehemija, sinu Hakalijevega. Zgodilo se je v mesecu Kislevu, v dvajsetem letu, ko sem bil na gradu Susanu,',
        2: 'da pride Hanani, eden bratov mojih, in ž njim nekaj mož z Judovega; in poprašam jih za Jude, ki so se rešili, ki so preostali iz ujetništva, in za Jeruzalem.',
        3: 'In oni mi reko: Tisti, kar jih je preostalo iz ujetništva, so ondi v deželi v veliki stiski in v zasramovanju; in zidovje Jeruzalema je razvaljeno in vrata njegova sežgana z ognjem.',
        4: 'In ko sem zaslišal te besede, sem sedel in jokal in žaloval nekoliko dni, in postil sem se ter molil pred Bogom nebes',
        5: 'in rekel: Prosim te, o Gospod, Bog nebes, Bog mogočni, veliki in grozni, ki hraniš zavezo in milost tistim, ki te ljubijo in izpolnjujejo zapovedi tvoje!',
        6: 'Pazijo naj, prosim, ušesa tvoja in oči tvoje naj bodo odprte, da poslušaš hlapca svojega molitev, ki jo molim pred teboj ta čas, po dne in po noči, za sinove Izraelove, hlapce tvoje, ko pripoznavam grehe sinov Izraelovih, ki smo jih zagrešili zoper tebe. Tudi mi, jaz in mojega očeta hiša, smo grešili.',
        7: 'Zelo krivo smo ravnali zoper tebe in nismo držali zapovedi, ne postav, ne sodb, ki si jih zapovedal hlapcu svojemu Mojzesu.',
        8: 'Spomni se, prosim, besede, ki si jo velel hlapcu svojemu Mojzesu, govoreč: Ako se izneverite, vas razkropim daleč med ljudstva;',
        9: 'ako se pa izpreobrnete k meni in boste držali zapovedi moje ter jih izpolnjevali, čeprav bi bili razskropljenci vaši ob koncu neba, tudi odondod jih zberem in jih privedem na kraj, ki sem ga izvolil, da umestim tam ime svoje.',
        10: 'Saj ti so hlapci tvoji in ljudstvo tvoje, ki si ga odrešil z veliko močjo svojo in z mogočno roko svojo.',
        11: 'Ah, Gospod, prosim, pazi naj uho tvoje na hlapca tvojega molitev in na molitev hlapcev tvojih, ki se želé bati imena tvojega, in dodeli danes uspeh hlapcu svojemu ter mu daj usmiljenje v očeh tega moža. – Bil sem namreč kraljev točaj.',
    },
    2: {
        1: 'Zgodi se pa v mesecu Nisanu, v dvajsetem letu kralja Artakserksa, ko je vino stalo pred njim, da vzamem vino in ga podam kralju. A prej nisem bil nikoli žalosten pred njim.',
        2: 'In kralj mi reče: Zakaj je obraz tvoj žalosten? saj nisi bolan? To ni nič drugega nego bolečina v srcu! Tedaj sem se silno bridko bal.',
        3: 'In rečem kralju: Kralj, živi vekomaj! Kako ne bi bil žalostnega obraza, ko pusto leži mesto, kjer je očetov mojih grobišče, in vrata njegova so z ognjem požgana!',
        4: 'Nato mi kralj reče: Kaj torej prosiš? V tem sem molil k Bogu nebes.',
        5: 'In rečem kralju: Ako se vidi dobro kralju in ako je hlapec tvoj prijeten v očeh tvojih, prosim, da me pošlješ na Judovo, v mesto, kjer so pokopani očetje moji, da ga pozidam.',
        6: 'In kralj mi veli (kraljica pa je sedela zraven njega): Koliko časa boš hodil? in kdaj se vrneš? In kralju je bilo ugodno, in me je poslal, ko sem mu določil čas.',
        7: 'Še sem rekel kralju: Ako se vidi kralju dobro, naj prejmem list do deželnih oblastnikov onostan reke, da mi dovolijo iti skozi svoje kraje, dokler ne pridem na Judovo;',
        8: 'in list Asafu, varuhu kraljevega gozda, da bi mi dal lesa, da napravim bruna za vrata gradu, ki je pri hiši, in za mestno obzidje in za hišo, v katero pojdem. In kralj mi jih je dal, ker je bila dobrotljiva roka Božja nad menoj.',
        9: 'In ko sem prišel k deželnim oblastnikom za reko, sem jim oddal kraljeve liste. Kralj pa je z menoj poslal vojne poveljnike in konjike.',
        10: 'Ko pa je slišal Sanbalat Horončan in hlapec Tobija, Amonec, ju je hudo peklo, da je prišel človek, da skrbi za blaginjo sinov Izraelovih.',
        11: 'In dospel sem v Jeruzalem. In ko sem bil ondi tri dni,',
        12: 'vstanem po noči in malo mož z menoj; nisem namreč povedal nobenemu človeku, kaj mi je bil dal moj Bog v srce, da storim za Jeruzalem; tudi ni bilo živinčeta pri meni razen tega, na katerem sem jezdil.',
        13: 'In jezdil sem ponoči skozi Dolinska vrata ven proti Zmajevemu studencu in h Gnojnim vratom in pregledoval zidovje Jeruzalemsko, ki je bilo razsuto in vrata njegova z ognjem požgana.',
        14: 'In šel sem dalje k Studenčnim vratom in h kraljevemu ribniku, a ondi ni bilo prostora mojemu živinčetu, da bi moglo iti pod mano.',
        15: 'Šel sem torej po noči gori ob potoku in pregledoval zidovje; potem sem se vrnil zopet skozi Dolinska vrata in prišel domov.',
        16: 'Načelniki pa niso vedeli, kam sem šel ali kaj sem delal, kajti doslej nisem bil ničesar povedal Judom in duhovnikom, ne plemenitnikom in načelnikom in drugim, ki so opravljali delo.',
        17: 'Tedaj sem jim rekel: Vidite nesrečo, v kateri smo, da Jeruzalem leži pust in njega vrata so sežgana z ognjem? Pojdimo in zidajmo zidovje jeruzalemsko, da ne bodemo več ljudem v zasrambo.',
        18: 'In povedal sem jim o roki svojega Boga, ki je bila dobrotljiva nad mano, tudi kraljeve besede, ki mi jih je bil govoril. Nato reko: Vstanimo in zidajmo! In potrjene so bile njih roke za dobro delo.',
        19: 'Ko je pa to slišal Sanbalat Horončan in Tobija hlapec, Amonec, in Gesem Arabec, so nas zasmehovali in nas zaničevali in dejali: Kaj pomeni to, kar počenjate? Hočete se li vi upreti kralju?',
        20: 'Tedaj sem jim odgovoril in rekel: Bog nebes nam da srečo, in mi, hlapci njegovi, hočemo vstati in zidati. Vam pa ni deleža, ne pravice, ne spomina v Jeruzalemu.',
    },
    3: {
        1: 'In Eliasib, veliki duhovnik, vstane z brati svojimi duhovniki in sezidajo Ovčja vrata ter jih posvetijo in vanje vstavijo duri. Posvetili so vse prav do stolpa Mea, do stolpa Hananela.',
        2: 'In poleg njega so zidali možje iz Jeriha. Zraven njega je tudi zidal Zakur, sin Imrijev.',
        3: 'Ribja vrata pa so sezidali sinovi iz Senaa; napravili so v njih bruna in vstavili vanje duri in njih ključalnice in zapahe.',
        4: 'Poleg njih je zidal Meremot, sin Urijev, sinu Hakozovega. In poleg njega je zidal Mesulam, sin Berekija, sinu Mesezabelovega. In poleg njiju je popravljal Zadok, sin Baanov.',
        5: 'In njim ob strani so popravljali Tekojčani; a njih imenitniki niso upognili vratu k službi svojega Gospoda.',
        6: 'In Stara vrata sta popravljala Jojada, sin Paseahov, in Mesulam, sin Besodejev: prekrila sta jih z bruni in vstavila vanje duri in njih ključalnice in zapahe.',
        7: 'In poleg njiju je popravljal Melatija Gibeonski in Jadon Meronotičan, možje iz Gibeona in iz Micpe, do tja, kjer je bila stolica deželnega oblastnika tostran reke.',
        8: 'Njim ob strani je popravljal Uziel, sin Harhajev, eden od zlatarjev. In poleg njega je popravljal Hananija, eden od lekarnikov. In so pustili Jeruzalem, kakor je bil, do širokega zida.',
        9: 'In poleg njega je popravljal Refaja, sin Hurov, glavar polovice kraja Jeruzalemskega.',
        10: 'In poleg njega je popravljal Jedaja, sin Harumafov, proti svoji hiši vprek. In poleg njega je popravljal Hatuš, sin Hasabnejev.',
        11: 'Malkija, sin Harimov, in Hašub, sin Pahat-moabov, sta pa popravljala drugi kos zidovja in Pečni stolp.',
        12: 'In poleg njiju je popravljal Salum, sin Halohešev, glavar druge polovice Jeruzalemskega kraja, on in hčere njegove.',
        13: 'Dolinska vrata je popravljal Hanun in prebivalci v Zanoahu; sezidali so jih ter vstavili vanje duri in njih ključalnice in zapahe in so zidali tisoč komolcev zidu do Gnojnih vrat.',
        14: 'Gnojna vrata pa je popravljal Malkija, sin Rehabov, glavar kraja Bet-keremskega; sezidal jih je in vtaknil duri vanje in njih ključalnice in zapahe.',
        15: 'Studenčna vrata pa je popravljal Salun, sin Kol-hozejev, glavar okraja Micpenskega; sezidal jih je ter pokril in vtaknil duri vanje in njih ključalnice in zapahe, in postavil je zid ob ribniku Silojskem pri kraljevem vrtu prav do stopnic, ki gredo doli iz mesta Davidovega.',
        16: 'Za njim je popravljal Nehemija, sin Azbukov, glavar polovice okraja Betzurskega, tja do konca nasproti grobom Davidovim in do ribnika, ki so ga bili napravili, in do hiše junakov.',
        17: 'Za njim so popravljali leviti, Rehum, sin Banijev. Poleg njega je popravlal Hasabija, glavar polovice okraja Keilskega, za svoj okraj.',
        18: 'Za njim so popravljali njih bratje, Bavaj, sin Henadadov, vladar druge polovice okraja Keilskega.',
        19: 'In poleg njega je popravljal Ezer, sin Jesujev, glavar v Micpi. Drugi kos zidu nasproti vzhodu k orožarni, pri zidnem ovinku.',
        20: 'Za njim je marljivo popravljal Baruk, sin Zabajev, drugi kos zidu, od ovinka k vratom hiše Eliasiba, velikega duhovnika.',
        21: 'Za njim je popravljal Meremot, sin Urijev, sinu Hakozovega, drugi kos zidu od vrat hiše Eleasibove do konca hiše Eliasibove.',
        22: 'In za njim so popravljali duhovniki, ki so prebivali na Jordanski ravnini.',
        23: 'Za njimi sta popravljala Benjamin in Hašub hišam svojim nasproti. Za njima je popravljal Azarija, sin Maaseja, sinu Ananijevega, pri hiši svoji.',
        24: 'Za njim je popravljal Binuj, sin Henadadov, drugi kos zidu, od hiše Azarijeve do ovinka in do vogla.',
        25: 'Palal, sin Uzajev, je popravljal proti ovinku in visokemu stolpu vprek, ki moli iznad hiše kraljeve, ki je ob dvoru jetnišnice; za njim pa Pedaja, sin Parošev.',
        26: '(Netinimci pa so stanovali na Ofelu do Vodnih vrat proti jutru in do stolpa, ki kvišku moli.)',
        27: 'Za njim so Tekojčani popravljali drugi kos zidu, nasproti visokemu stolpu, ki kvišku moli, in do zidu Ofela.',
        28: 'Od konjskih vrat gori so popravljali duhovniki vsak hiši svoji nasproti.',
        29: 'Za njimi je popravljal Zadok, sin Imerjev, hiši svoji nasproti. In za njim je popravljal Semaja, sin Sekanijev, varuh Vzhodnih vrat.',
        30: 'Za njim je popravljal Hananija, sin Selemijev, in Hanun, šesti sin Zalafov, drugi kos zidu. Za njim je popravljal Mesulam, sin Berekijev, hramu svojemu nasproti.',
        31: 'Za njim je popravljal Malkija, eden od zlatarjev, do hiše Netinimcev in trgovcev, vratom Mifkadovim nasproti, in do stolpove veže na voglu.',
        32: 'In med vežo stolpovo in Ovčjimi vrati so popravljali zlatarji in trgovci.',
    },
    4: {
        1: 'In ko je slišal Sanbalat, da stavimo obzidje, mu to silno zamrzi in se razjezi ter zasmehuje Jude.',
        2: 'In govori pred brati svojimi in pred vojsko v Samariji in reče: Kaj delajo ti slabotni Judje? Ali naj se jim to pripusti? Bodo li darovali? bodo li neki dan dokončali? hočejo li v življenje povrniti kamenje z grobljišča, ki je vendar sežgano?',
        3: 'Tobija Amonec, stoječ poleg njega, reče: Karkoli naj zidajo, če lisica pride nanj, poruši njih kameneni zid!',
        4: 'Poslušaj, o naš Bog, ker smo zaničevani, in obrni njih zasmehovanje njim na glavo ter izroči jih oplenjenju v deželi ujetništva!',
        5: 'Ne zakrivaj njih krivice in ne izbriši njih greha izpred obličja svojega! Ker so te dražili v jezo spričo zidalcev. –',
        6: 'Mi pa smo zidali obzidje, in smo sklenili ves zid okrog do polovice višave, kajti ljudstvo je imelo pogum za delo.',
        7: 'Ko pa so slišali Sanbalat in Tobija in Arabci in Amonci in Asdodci, da napreduje popravljanje zidovja jeruzalemskega in da že zazidavamo, kar je bilo razdrto, tedaj se silno razjeze.',
        8: 'In vsi se vkup zarote, da pojdejo bojevat se zoper Jeruzalem in delat zmešnjavo v njem.',
        9: 'Mi pa smo molili k Bogu svojemu in postavili stražo zoper nje, dan in noč, boječ se jih.',
        10: 'In Juda reče: Moč je bremenarjem oslabela in groblje so še velike, tako da ne moremo zidati zidu.',
        11: 'Naši nasprotniki so pa rekli: Ne bodo zvedeli, ne videli, dokler ne pridemo mednje ter jih pobijemo, in tako ustavimo delo.',
        12: 'Zgodi se pa, ko so prišli Judje, ki so poleg njih prebivali, in so nam dobro desetkrat povedali, od vseh krajev: Morate se vrniti k nam!',
        13: 'tedaj sem postavil na spodnje kraje prostora za zidom, na goljave, ljudstvo po njih rodovinah ž njih meči, sulicami in loki.',
        14: 'In ko sem vse ogledal, sem vstal in velel plemenitnikom in načelnikom in drugemu ljudstvu: Nikar se jih ne bojte, spominjajte se Gospoda, velikega in groznega, in bojujte se za brate svoje, za sinove in hčere svoje, za žene in hiše svoje!',
        15: 'Ko so pa slišali sovražniki naši, da nam je bilo povedano, in je Bog uničil njih naklep, smo se vrnili vsi na zid, vsak k delu svojemu.',
        16: 'In bilo je od tega dne, da je polovica mojih hlapcev opravljala delo, druga polovica pa je držala sulice in ščite, loke in oklepe, in poglavarji so stali za vso družino Judovo,',
        17: 'ki je delala na zidu. In bremenarji so nakladali, vsak z eno roko delajoč, z drugo pa držeč orožje.',
        18: 'In zidar je vsak imel meč pripasan k ledju, in tako so zidali. In trobentač je stal poleg mene.',
        19: 'In dejal sem plemenitnikom in načelnikom in drugemu ljudstvu: Dela je veliko in na široko in daleč smo narazen raztrošeni po zidu;',
        20: 'na kateremkoli kraju zaslišite trobente glas, tja se zberite k nam. Bog naš se bo bojeval za nas!',
        21: 'Tako smo se trudili pri delu in polovica jih je držala sulice od jutranje zarje, dokler so zvezde prisvetile.',
        22: 'Tudi sem velel tisti čas ljudstvu: Slednji ostani s hlapcem svojim čez noč v Jeruzalemu, da nam bodo po noči v stražo in po dne za delo!',
        23: 'Niti jaz, ne bratje moji, ne možje na straži za mano, nihče ni slekel obleke, vsakemu je bilo orožje ob desnici.',
    },
    5: {
        1: 'In nastalo je veliko vpitje ljudstva in njih žen zoper svoje brate, Jude.',
        2: 'Nekateri so namreč bili, ki so dejali: Naših sinov in naših hčerá, nas je veliko: moramo dobiti žita, da jemo in ostanemo živi.',
        3: 'In nekateri so bili, ki so govorili: Morali smo zastaviti njive svoje, vinograde in hiše svoje, da smo dobili žita ob tej draginji.',
        4: 'Nekateri pa so dejali: Izposodili smo si denarja na svoje njive in vinograde za davke kralju.',
        5: 'Vendar pa je telo naše kakor naših bratov telo in naši otroci so kakor njih otroci. In glej, moramo deti sinove in hčere svoje pod jarem sužnosti, in nekatere naše hčere so že pod jarmom, in ni v moči naših rok, da jih odkupimo; saj imajo drugi njive in vinograde naše.',
        6: 'Ko sem pa slišal njih vpitje in take besede, sem se silno razsrdil.',
        7: 'In posvetoval sem se sam pri sebi v srcu ter potem okaral plemenitnike in načelnike in jim dejal: Vi lihvarite, vsak proti bratu svojemu! In priredil sem veliko zborovanje zoper nje',
        8: 'in jim dejal: Mi smo odkupili, kolikor smo jih mogli, brate svoje, Jude, ki so bili prodani poganom. Vi pa hočete prodajati brate svoje? in nam li naj se prodado? Nato so molčali in niso vedeli odgovoriti.',
        9: 'Še sem rekel: Kar delate, ni dobro. Ne bi li imeli hoditi v strahu Boga našega, da ne bodemo v zasmeh poganom, sovražnikom svojim?',
        10: 'Pa tudi jaz, bratje moji in hlapci moji, smo jim posodili denarja in žita za obresti. Prosim vas, odpustímo jim to posojilo!',
        11: 'Povrnite jim, prosim, še danes njih njive in vinograde, njih oljkove vrte in hiše in stotnino denarja in žita, vina in olja, ki ste ga jim posojali na obresti.',
        12: 'Tedaj reko: Povrnemo jim in ne bomo jih terjali za nič, ampak hočemo storiti, kakor praviš. Nato pokličem duhovnike in jih zavežem s prisego, da store po tej obljubi.',
        13: 'Iztresel sem tudi nedrije svoje, rekoč: Tako iztresi Bog vsakega, ki ne izpolni te obljube, iz hiše njegove in s posla njegovega, in tako bodi iztresen in prazen! In ves zbor je dejal: Amen! in so hvalili Gospoda. In ljudstvo je storilo po tej obljubi.',
        14: 'Tudi od časa, ko mi je bilo ukazano, naj bodem njih deželni poglavar v deželi Judovi, namreč od dvajsetega do dvaintridesetega leta kralja Artakserksa, dvanajst let, nisem živil sebe in bratov svojih s poglavarjevim živežem.',
        15: 'Ali prejšnji deželni oblastniki, ki so bili pred menoj, so nadlegovali ljudstvo in so jemali od njih živeža in vina, vrhutega po štirideset seklov srebra, in še njih hlapci so samovoljno gospodovali ljudstvu. A jaz nisem ravnal tako, zaradi Božjega strahu.',
        16: 'Pa tudi dela na zidu sem se udeležil, in njive nismo nobene kupili in vsi moji hlapci so ondi morali prihajati na delo.',
        17: 'Vrhutega so jedli pri moji mizi Judje in načelniki, sto in petdeset mož, in tisti, ki so k nam dohajali izmed poganov v okolišu.',
        18: 'In pripravili so mi vsak dan: enega vola in šest izbranih ovac, tudi perotnine so mi pripravljali in enkrat v desetih dneh zalogo vsakovrstnega vina; pri vsem tem nisem zahteval živeža deželnega oblastnika, ker služba je hudo težila ljudstvo.',
        19: 'Spominjaj se mi, o Bog moj, v dobro vsega, kar sem storil za to ljudstvo.',
    },
    6: {
        1: 'Zgodi se pa, ko so zvedeli Sanbalat, Tobija in Gesem Arabec in drugi naših sovražnikov, da sem dozidal obzidje ter da v njem ni bilo več vrzeli (dasi še nisem do tedaj obesil durnic na vrata),',
        2: 'da pošljeta k meni Sanbalat in Gesem ter sporočita: Pridi, in naj se snidemo v kateri vasi na Onski ravnini. Ona sta pa mislila storiti mi hudo.',
        3: 'In pošljem sle in jima sporočim: Opravljam veliko delo, ne morem priti tja doli. Čemu naj počiva delo, če bi ga popustil in prišel doli k vam?',
        4: 'Štirikrat sta k meni poslala z istimi besedami, in odgovarjal sem jima na ta način.',
        5: 'Tedaj pošlje Sanbalat petič istotako hlapca svojega k meni z odprtim listom v roki,',
        6: 'v katerem je bilo pisano: Pripoveduje se med narodi, in Gesem to pravi, da se ti in Judje mislite izneveriti; zato gradiš obzidje, in ti jim hočeš biti kralj, kakor se govori.',
        7: 'In postavil si tudi proroke, da oznanjajo o tebi v Jeruzalemu, govoreč: Kralj je na Judovem! In sedaj lahko zasliši kralj to, kar se govori. Sedaj torej pridi, da se posvetujemo skupaj!',
        8: 'Nato pošljem k njemu in sporočim: Nič takega se ni zgodilo, kar ti praviš, temuč v srcu svojem si to izmislil.',
        9: 'Zakaj vsi oni so nas hoteli prestrašiti, češ, da bodo roke naše nehale od dela, da se ne dovrši. –Sedaj pa, Bog, pokrepčaj moje roke!',
        10: 'In šel sem v hišo Semaja, sinu Delaja, sinu Mehetabela, ki se je bil zaklenil. In on je rekel: Snidiva se v hiši Božji, sredi templja, in zapriva duri templjeve; zakaj pridejo, da te umore, po noči pridejo, da te ubijejo!',
        11: 'Jaz pa sem dejal: Mož, kakršen sem jaz, naj beži? In kako bi smel tak, kakršen sem jaz, iti v tempelj, da ostane živ? Ne pojdem vanj!',
        12: 'In razpoznal sem, da ga ni poslal Bog, temuč govoril je to prorokovanje zoper mene, in Tobija in Sanbalat sta mu bila dala denarja',
        13: 'in je bil najet v ta namen, da se zbojim in storim tako in se pregrešim in da bi imela kaj hudega poročati, da bi me mogla zasramovati.',
        14: 'Spominjaj se, moj Bog, Tobija in Sanbalata, primerno tem njiju delom, in tudi prorokinje Noadije in drugih prorokov, ki so me hoteli spraviti v strah.',
        15: 'In obzidje je bilo dokončano petindvajseti dan meseca Elula, v dvainpetdesetih dneh.',
        16: 'In ko so to slišali vsi sovražniki naši, so se zbali vsi pogani, ki so živeli okoli nas, in bili so zelo uplašeni sami v sebi, kajti spoznali so, da je to delo dognal Bog.',
        17: 'Tudi so v teh dneh plemenitniki Judovi pošiljali mnogo listov Tobiju, jim pa so dohajali listi od Tobija.',
        18: 'Dosti jih je namreč bilo na Judovem, ki so se ž njim bili s prisego zvezali, ker je bil zet Sekanija, sinu Arahovega, in se je sin njegov Johanan oženil s hčerjo Mesulama, sinu Berekijevega.',
        19: 'Govorili so tudi vpričo mene o njegovih dobrih dejanjih in njemu skrivaj donašali besede moje; in Tobija je pošiljal liste, da bi me spravil v strah.',
    },
    7: {
        1: 'In ko je bilo obzidje dodelano, sem obesil durnice nanje, in vratarji in pevci in leviti so bili postavljeni v službo.',
        2: 'In brata svojega Hanana in Hananija, višjega v gradu, sem postavil nad Jeruzalemom, zakaj bil je zvest mož in bogaboječ mimo mnogih drugih.',
        3: 'In sem jima velel: Vrata jeruzalemska naj se ne odpirajo, dokler solnce vroče ne sije; in dokler še stoje na straži, naj zaprejo duri, in zaklenita jih. In postavita straže iz prebivalcev jeruzalemskih, vsakega na stražišče njegovo in vsakega nasproti hiši njegovi.',
        4: 'Mesto pa je bili prostrano na vse strani in veliko, a malo ljudstva v njem, in hiše niso bile pozidane.',
        5: 'In Bog moj mi je dal v srce, da sem zvabil plemenitnike in načelnike in ljudstvo, da bi jih preštel po rodovih. In našel sem zapis rodov tistih, ki so prišli prvi gori iz Babilona, in našel sem v njem pisano takole:',
        6: 'Ti so otroci pokrajine Judove, ki so šli gori iz ujetništva izmed tistih, ki so bili pripeljani, ki jih je preselil Nebukadnezar, kralj babilonski, in ki so se povrnili v Jeruzalem in na Judovo, vsak v mesto svoje;',
        7: 'ki so prišli z Zerubabelom, Jesuom, Nehemijem, Azarijem, Raamijem, Nahamanom, Mardohejem, Bilsanom, Misperetom, Bigvajem, Nehumom, Baanom. Število mož iz ljudstva Izraelovega:',
        8: 'Sinov Paroševih dva tisoč in sto in dvainsedemdeset.',
        9: 'Sinov Sefatijevih tristo in dvainsedemdeset.',
        10: 'Sinov Arahovih šeststo dvainpetdeset.',
        11: 'Sinov Pahat-moaba, od sinov Jesujevih in Joabovih, dva tisoč in osemsto osemnajst.',
        12: 'Sinov Elamovih tisoč dvesto štiriinpetdeset.',
        13: 'Sinov Zatujevih osemsto petinštirideset.',
        14: 'Sinov Zakajevih sedemsto in šestdeset.',
        15: 'Sinov Binujevih šeststo oseminštirideset.',
        16: 'Sinov Bebajevih šeststo osemindvajset.',
        17: 'Sinov Azgadovih dva tisoč tristo dvaindvajset.',
        18: 'Sinov Adonikamovih šeststo sedeminšestdeset.',
        19: 'Sinov Bigvajevih dva tisoč sedeminšestdeset.',
        20: 'Sinov Adinovih šeststo petinpetdeset.',
        21: 'Sinov Aterjevih, od Hezekija, osemindevetdeset.',
        22: 'Sinov Hasumovih tristo osemindvajset.',
        23: 'Sinov Bezajevih tristo štiriindvajset.',
        24: 'Sinov Harifovih sto in dvanajst.',
        25: 'Sinov Gibeonovih petindevetdeset.',
        26: 'Mož iz Betlehema in Netofe sto oseminosemdeset.',
        27: 'Mož iz Anatota sto osemindvajset.',
        28: 'Mož iz Bet-azmaveta dvainštirideset.',
        29: 'Mož iz Kirjat-jearima, Kefire in Beerota sedemsto triinštirideset.',
        30: 'Mož iz Rame in Gebe šeststo edenindvajset.',
        31: 'Mož iz Mikmasa sto dvaindvajset.',
        32: 'Mož iz Betela in Aja sto triindvajset.',
        33: 'Mož iz drugega Neba dvainpetdeset.',
        34: 'Sinov drugega Elama tisoč dvesto štiriinpetdeset.',
        35: 'Sinov Harimovih tristo in dvajset.',
        36: 'Sinov Jerihovih tristo petinštirideset.',
        37: 'Sinov iz Loda, Hadida in Ona sedemsto edenindvajset.',
        38: 'Sinov iz Senaa tri tisoč devetsto in trideset.',
        39: 'Duhovnikov: sinov Jedajevih, iz hiše Jesujeve, devetsto triinsedemdeset.',
        40: 'Sinov Imerjevih tisoč dvainpetdeset.',
        41: 'Sinov Pashurjevih tisoč dvesto sedeminštirideset.',
        42: 'Sinov Harimovih tisoč in sedemnajst.',
        43: 'Levitov: sinov Jesujevih, od Kadmiela, od sinov Hodevovih, štiriinsedemdeset.',
        44: 'Pevcev: sinov Asafovih sto oseminštirideset.',
        45: 'Vratarjev: sinov Salumovih, sinov Aterjevih, sinov Talmonovih, sinov Akubovih, sinov Hatitovih, sinov Sobajevih: sto osemintrideset.',
        46: 'Netinimci: sinovi Zihovi, sinovi Hasufovi, sinovi Tabaotovi,',
        47: 'sinovi Kerosovi, sinovi Siahovi, sinovi Padonovi,',
        48: 'sinovi Lebanovi, sinovi Hagabovi, sinovi Salmajevi,',
        49: 'sinovi Hananovi, sinovi Gidelovi, sinovi Gaharjevi,',
        50: 'sinovi Reajevi, sinovi Rezinovi, sinovi Nekodovi,',
        51: 'sinovi Gazamovi, sinovi Uzovi, sinovi Paseahovi,',
        52: 'sinovi Bezajevi, sinovi Meunimov, sinovi Nefusimov,',
        53: 'sinovi Bakbukovi, sinovi Hakufovi, sinovi Harhurjevi,',
        54: 'sinovi Bazlitovi, sinovi Mehidovi, sinovi Harsovi,',
        55: 'sinovi Barkosovi, sinovi Siserjevi, sinovi Tamahovi,',
        56: 'sinovi Neziahovi, sinovi Hatifovi.',
        57: 'Sinovi hlapcev Salomonovih: sinovi Sotajevi, sinovi Soferetovi, sinovi Peridovi,',
        58: 'sinovi Jaalovi, sinovi Darkonovi, sinovi, Gidelovi,',
        59: 'sinovi Sefatijevi, sinovi Hatilovi, sinovi Poheret-hazebaimovi, sinovi Amonovi.',
        60: 'Vseh Netinimcev in sinov hlapcev Salomonovih je bilo tristo dvaindevetdeset.',
        61: 'Ti pa so bili, ki so šli gori iz Telmelaha, Telharsa, Keruba, Adona in Imerja, toda niso mogli izkazati hiš svojih očetov, ne svojega rodu, ali so iz Izraela:',
        62: 'sinovi Delajevi, sinovi Tobijevi, sinovi Nekodovi, šeststo dvainštirideset.',
        63: 'In od duhovnikov: sinovi Hobajevi, sinovi Hakozovi, sinovi Barzilaja, ki si je vzel ženo iz hčerá Barzilaja Gileadčana in je bil imenovan po njih imenu.',
        64: 'Ti so iskali zapis svojih rodov, pa ga niso našli, zato so jih šteli za nečiste za duhovništvo.',
        65: 'In Tirsata jim je velel, da naj ne jedo od najsvetejšega, dokler ne vstane duhovnik z Urimom in Tumimom.',
        66: 'Ves zbor je štel dvainštirideset tisoč tristo in šestdeset,',
        67: 'brez njih hlapcev in dekel, katerih je bilo sedem tisoč tristo sedemintrideset; imeli so tudi dvesto petinštirideset pevcev in pevk.',
        68: 'Njih konj je bilo sedemsto šestintrideset, njih mezgov dvesto petinštirideset,',
        69: 'velblodov štiristo petintrideset in oslov šesttisoč sedemsto in dvajset.',
        70: 'In nekateri izmed poglavarjev očetovin so dali v prospeh dela. Tirsata je dal v zaklad: zlata tisoč darikov, petdeset čaš, petsto in trideset duhovniških sukenj.',
        71: 'In nekateri iz poglavarjev očetovin so dali v zaklad za delo: zlata dvajset tisoč darikov in srebra dva tisoč in dvesto min.',
        72: 'In tega, kar so dali drugi iz ljudstva, je bilo v zlatu dvajset tisoč darikov in v srebru dva tisoč min in sedeminšestdeset duhovniških sukenj.',
        73: 'In duhovniki in leviti, vratarji in pevci in nekateri iz ljudstva in Netinimci in vsi Izraelci so se naselili v svoja mesta. In ko je prišel sedmi mesec, so bili sinovi Izraelovi že v svojih mestih.',
    },
    8: {
        1: 'Tedaj se je zbralo vse ljudstvo kakor en mož na široki ulici pred Vodnimi vrati; in rekli so Ezru pismouku, naj prinese knjigo zakona Mojzesovega, ki ga je Gospod zapovedal Izraelu.',
        2: 'In Ezra duhovnik je prinesel postavo pred zbor, pred može in žene in vse, ki so jo mogli slišati in razumeti, prvi dan sedmega meseca.',
        3: 'In čital jo je na široki ulici, ki je pred Vodnimi vrati, od jutranjega svita do poldne vpričo mož in žen in tistih, ki so mogli razumeti; in vsega ljudstva ušesa so bila obrnjena h knjigi postave.',
        4: 'In Ezra, pismouk, je stal na visokem lesenem stolu, ki so ga bili napravili v ta namen; in zraven njega so stali Matitija, Sema, Anaja, Urija, Hilkija in Maaseja, njemu na desni, na levi pa Pedaja, Misael, Malkija, Hasum, Hasbadana, Zeharija in Mesulam.',
        5: 'In Ezra razgane knjigo pred očmi vsega ljudstva (kajti stal je više nego vse ljudstvo), in ko jo je razganil, vstane vse ljudstvo.',
        6: 'In Ezra hvali Gospoda, vélikega Boga. In vse ljudstvo odgovori: Amen, Amen! povzdigujoč roke svoje. In pripognejo se in poklonijo Gospodu z obrazom do tal.',
        7: 'Tudi Jesua, Bani, Serebija, Jamin, Akub, Sabetaj, Hodija, Maaseja, Kelita, Azarija, Jozabad, Hanan, Pelaja, leviti, so razlagali ljudstvu pouk postave; in ljudstvo je stalo na mestu svojem.',
        8: 'In čitali so knjigo, postavo Božjo, razumljivo in razložili pomen, da se je prečitano razumelo.',
        9: 'In Nehemija, ki je bil Tirsata, in Ezra, duhovnik pismouk, in leviti, ki so učili ljudstvo, so rekli vsemu ljudstvu: Ta dan je svet Gospodu, vašemu Bogu; ne bodite žalostni in ne plakajte! Zakaj vse ljudstvo je plakalo, ko so slišali besede postave.',
        10: 'Zato jim je velel: Pojdite, jejte tolsto in pijte sladko in pošljite tudi darila tem, ki niso ničesar zase pripravili, zakaj ta dan je svet Gospodu našemu; zato se ne žalostite, kajti radost Gospodova je vaša moč.',
        11: 'In leviti so tolažili vse ljudstvo, govoreč: Molčíte, kajti ta dan je svet, ne žalostite se!',
        12: 'In šlo je vse ljudstvo, da bi jedli in pili in darila pošiljali in napravili veliko veselico; kajti razumeli so besede, ki so jih jim bili oznanjali.',
        13: 'In drugega dne so se zbrali poglavarji očetovin vsega ljudstva, duhovniki in leviti k Ezru pismouku, da bi pazili na besede postave.',
        14: 'In našli so pisano v postavi, da je bil Gospod zapovedal po Mojzesu, da naj prebivajo sinovi Izraelovi v šatorih iz zelenja ob prazniku v sedmem mesecu',
        15: 'ter naj oznanijo in pošljejo oklic po vseh mestih svojih in po Jeruzalemu, rekoč: Pojdite na gore in prinesite oljkovih mladik in vej z divje oljke in mirtovih in palmovih vej in mladičja z listnatih dreves, da se napravijo iz njih šatori, kakor je pisano!',
        16: 'Ljudstvo je torej šlo ven, in so prinesli ter si napravili šatore, vsak na strehi svoji, in na svojih dvoriščih in na dvoriščih hiše Božje in na široki ulici pri Vodnih vratih in na široki ulici pri Efraimovih vratih.',
        17: 'In ves zbor tistih, ki so se bili vrnili iz ujetništva, si je napravil šatore, in prebivali so v njih. Kajti sinovi Izraelovi niso bili tako slovesno praznovali od dni Jozueta, sina Nunovega, do tega dne. In bilo je veselje silno veliko.',
        18: 'In bral je v knjigi Božje postave vsak dan, od prvega dne do poslednjega. In so praznovali praznik sedem dni, in osmi dan je bilo slovesno zborovanje, po predpisu.',
    },
    9: {
        1: 'A štiriindvajseti dan tega meseca so se zbrali sinovi Izraelovi s postom in v žalni obleki in s prstjo na glavi.',
        2: 'In seme Izraelovo se je ločilo od vseh otrok tujcev, in ustopili so se in pripoznavali grehe svoje in očetov svojih kriva dejanja.',
        3: 'In stali so na mesto svojem in so brali v knjigi postave Gospoda, svojega Boga, četrti del dne. In drugi četrti del dne so pripoznavali in se poklanjali Gospodu, svojemu Bogu.',
        4: 'Nato stopijo na stopnice levitov Jesua, Bani, Kadmiel, Sebanija, Buni, Serebija, Bani in Kenani, in so vpili z velikim glasom h Gospodu, svojemu Bogu.',
        5: 'In leviti: Jesua, Kadmiel, Bani, Hasabneja, Serebija, Hodija, Sebanija in Petahija so dejali: Vstanite in hvalite Gospoda, svojega Boga, od vekomaj do vekomaj! In hvaljeno bodi ime slave tvoje, ki je vzvišeno nad vsako hvalo in proslavo.',
        6: 'Ti si Gospod, ti edini! Ti si naredil nebo, nebesa nebes in vso njih vojsko, zemljo in vse, kar je na njej, morja in karkoli je v njih, in ti jim vsem vzdržuješ obstanek; in vojske nebeške te molijo.',
        7: 'Ti si Jehova, Bog, ki si izvolil Abrama ter ga pripeljal iz Ura Kaldejcev, in dal si mu ima Abraham.',
        8: 'In našel si srce njegovo zvesto pred seboj ter sklenil ž njim zavezo, da mu daš deželo Kanaancev, Hetejcev, Amorejcev, Ferizejcev, Jebusejcev in Girgasejcev, da jo daš semenu njegovemu, in si vzdržal besede svoje, zakaj ti si pravičen.',
        9: 'Ti si videl nadlogo očetov naših v Egiptu in slišal njih vpitje ob Rdečem morju;',
        10: 'in storil si znamenja in čudeže nad Faraonom in nad vsemi hlapci njegovimi in nad vsem ljudstvom dežele njegove, zakaj vedel si, da so prevzetno ravnali proti njim; in si sebi storil ime, kakor je današnji dan.',
        11: 'Razklal si morje pred njimi, da so šli sredi morja po suhem; njih preganjalce pa si vrgel v globočine, kakor kamen v silne vode.',
        12: 'In vodil si jih v oblakovem stebru po dne in v ognjenem stebru po noči, da bi jim svetil na poti, ki so po njej šli.',
        13: 'In prišel si doli na goro Sinaj in govoril si ž njimi iz nebes ter jim dal pravične sodbe in zakone resnične ter dobre postave in zapovedi;',
        14: 'in znano si jim storil sveto soboto svojo in jim zapovedal zapovedi in postave in zakon po Mojzesu, hlapcu svojem.',
        15: 'In kadar so bili lačni, si jim dajal kruha iz nebes in izpeljal si zanje vodo iz skale, ko so bili žejni, in si jim velel, naj gredo posest deželo, za katero si s povzdignjeno roko prisegel, da jim jo daš.',
        16: 'Ali oni, očetje naši, so ravnali prevzetno in postali so trdovratni in niso poslušali zapovedi tvojih',
        17: 'in so se branili poslušati in se niso spominjali čudovitih del tvojih, ki si jih storil med njimi, temuč v trdovratnosti svoji in v uporu svojem so si postavili glavarja, da bi se vrnili v sužnost svojo. Ali ti si Bog mnogega odpuščanja, milostiv in poln usmiljenja, počasen v jezi in obilen v milosti, ti jih nisi zapustil.',
        18: 'Ko so si celo naredili ulito tele in rekli: To je tvoj Bog, ki te je izpeljal iz Egipta, in so počenjali grozno zasmehovanje Boga,',
        19: 'ti jih vendar nisi zapustil v mnogoterem usmiljenju svojem v puščavi: oblakov steber se ni umaknil iznad njih po dne, da bi jih vodil po poti, ne ognjeni steber po noči, da bi jim svetil na pot, po kateri naj gredo.',
        20: 'Ti si tudi dal dobrega duha svojega, da jih poučuje, in njih ustom nisi odrekel mane svoje, in dajal si jim vode, ko so bili žejni.',
        21: 'Štirideset let si jih oskrboval v puščavi, da jim ničesar ni pomanjkovalo; njih obleka se ni razdrapala in njih noge niso otekle.',
        22: 'In dal si jim kraljestva in ljudstva in ta jim pridelil po posameznih pokrajinah; tako so posedli deželo Sihona, kralja hesbonskega, in deželo Oga, kralja v Basanu.',
        23: 'In njih otroke si pomnožil kakor zvezde na nebu in si jih pripeljal v deželo, za katero si bil govoril njih očetom, da pridejo vanjo in jo posedejo;',
        24: 'njih otroci so torej prišli vanjo in jo posedli, in ti si ponižal pred njimi prebivalce te dežele, Kanaance, in si jih dal njim v roke ž njih kralji in z ljudstvi vred v deželi, da so ž njimi storili po volji svoji.',
        25: 'In zavzeli so utrjena mesta in mastno zemljo in dobili v last hiše, polne vsakršnega blaga, vodnjake izkopane, vinograde, oljkove vrte in sadnih dreves obilo: in jedli so in se nasitili in odebeleli, dobro živeč po veliki dobroti tvoji.',
        26: 'Ali postali so nepokorni in se uprli zoper tebe in so vrgli zakon tvoj za hrbet svoj in pomorili proroke tvoje, ki so pričevali zoper nje, da bi jih zopet preobrnili k tebi, in so počenjali grozno zasmehovanje Boga.',
        27: 'Zato si jih dal v roke njih zatiralcem, ki so jih tlačili; ali ko so ob času nadloge vpili k tebi, ti si jih uslišal iz nebes in po svojem mnogoterem usmiljenju si jim dal rešitelje, ki so jih oteli iz roke njih zatiralcev.',
        28: 'A komaj so imeli pokoj, so zopet delali hudo pred teboj. Zato si jih prepustil pesti njih sovražnikov, da so jim gospodovali; pa zopet so vpili k tebi, in slišal si jih iz nebes in mnogokrat si jih otel po mnogem usmiljenju svojem.',
        29: 'In pričeval si zoper nje, da bi jih izpreobrnil k postavi svoji, oni pa so se vedli prevzetno in niso poslušali zapovedi tvojih, ampak so grešili zoper pravice tvoje (katere kdor izpolnjuje, bo živel po njih) in pleča svoja umeknili izpod jarma tvojega; vdali so se trdovratnosti in niso hoteli poslušati.',
        30: 'A veliko let si imel potrpljenje ž njimi in po duhu svojem si pričeval zoper nje, po svojih prorokih, a niso poslušali; zato si jih dal v roke ljudstvom dežel.',
        31: 'Vendar pa v mnogoterem usmiljenju svojem jih nisi docela pokončal, ne jih zapustil, zakaj ti, Bog mogočni, si milostiv in poln usmiljenja.',
        32: 'In sedaj, o Bog naš, Bog mogočni, veliki, silni in grozni, ki hraniš zavezo in milost, naj se ti ne vidi majhna vsa tista težava, ki je zadela nas in kralje naše in kneze in duhovnike in proroke in očete naše in vse ljudstvo tvoje, od dni kraljev asirskih do tega dne.',
        33: 'Ali ti si pravičen v vsem, kar je prišlo nad nas: zakaj ti si ravnal po resnici, mi pa smo delali krivično.',
        34: 'In naši kralji, knezi, duhovniki in očetje niso delali po postavi tvoji in niso pazili na zapovedi tvoje in pričevanja, s katerimi si pričeval zoper nje.',
        35: 'Kajti niso ti služili v kraljestvu svojem in ob veliki dobroti tvoji, ki si jo jim podeljeval, in v tej postrani in mastni deželi, ki si jo jim bil izročil, in se niso preobrnili od hudih dejanj svojih.',
        36: 'Glej, hlapci smo danes, in dežela, ki si jo dal očetom našim, da uživajo njene sadove in dobrote – glej, v tej smo hlapci!',
        37: 'In ona dohodke svoje množi kraljem, ki si jih nam postavil zavoljo grehov naših, in ti gospodujejo telesom našim in živini naši, kakor jim je drago, in v veliki smo nadlogi.',
        38: 'A pri vsem tem narejamo in pišemo trdno zavezo, in vojvode naši, leviti in duhovniki naši, jo s pečati potrjujejo.',
    },
    10: {
        1: 'Ti pa, ki so pečatili, so bili: Nehemija Tirsata, sin Hakalijev, in Zedekija,',
        2: 'Seraja, Azarija, Jeremija,',
        3: 'Pashur, Amarija, Malkija,',
        4: 'Hatuš, Sebanija, Maluk,',
        5: 'Harim, Meremot, Obadija,',
        6: 'Daniel, Gineton, Baruk,',
        7: 'Mesulam, Abija, Mijamin,',
        8: 'Maazija, Bilgaj, Semaja: ti so bili duhovniki.',
        9: 'Leviti pa: Jesua, sin Azanijev, Binuj iz sinov Henadovih, Kadmiel,',
        10: 'in njih bratje: Sebanija, Hodija, Kelita, Pelaja, Hanan,',
        11: 'Miha, Rehob, Hasabija,',
        12: 'Zakur, Serebija, Sebanija,',
        13: 'Hodija, Bani, Beninu.',
        14: 'Poglavarji ljudstva: Paroš, Pahat-moab, Elam, Zatu, Bani,',
        15: 'Buni, Azgad, Bebaj,',
        16: 'Adonija, Bigvaj, Adin,',
        17: 'Ater, Hezekija, Azur,',
        18: 'Hodija, Hasum, Bezaj,',
        19: 'Harif, Anatot, Nobaj,',
        20: 'Magpias, Mesulam, Hezir,',
        21: 'Mesezabel, Zadok, Jadua,',
        22: 'Pelatija, Hanan, Anaja,',
        23: 'Hosea, Hananija, Hašub,',
        24: 'Haloheš, Pilha, Sobek,',
        25: 'Rehum, Hasabna Maaseja,',
        26: 'in Ahija, Hanan, Anan,',
        27: 'Maluk, Harim, Baana.',
        28: 'In drugo ljudstvo, duhovniki, leviti, vratarji, pevci, Netinimci in vsi, ki so se bili ločili od ljudstev dežel za postavo Božjo, njih žene, njih sinovi in hčere, katerikoli so bili razsodni in pametni,',
        29: 'so se oklenili bratov svojih, svojih plemenitnikov, in so vzeli nase prekletje in prisego, da bodo živeli po zakonu Božjem, ki je bil dan po Mojzesu, hlapcu Božjem, in da bodo hranili in izpolnjevali vse zapovedi Jehove, Gospoda našega, in sodbe in postave njegove;',
        30: 'ter da ne bomo dajali hčer svojih ljudem dežele, ne jemali njih hčer sinom svojim,',
        31: 'in kadar ljudje dežele prineso blaga ali kakršnegakoli živeža naprodaj sobotni dan, da ne kupimo od njih ob soboti in ob svetih dneh, in da se odpovemo pravice do sedmega leta in do vsakega posojila v njem.',
        32: 'In zavezali smo se z naredbo, da si naložimo na leto tretjino sekla za službo hiše Boga svojega:',
        33: 'za razvrstitev kruhov in za stalno jedilno daritev in za stalno žgalno daritev in za posebno ob sobotah in v začetku mesecev in ob določenih praznikih, in za svete reči in za daritev za greh v poravnavo za Izraela in za vse opravilo v hiši Boga svojega.',
        34: 'In žrebali smo, duhovniki, leviti, in ljudstvo, za daritev drv, da bi jih prinašali vsako leto, ob določenih časih, po hišah svojih očetov, v hišo Boga svojega, da bodo gorela na oltarju Gospoda, našega Boga, kakor je pisano v postavi;',
        35: 'in smo se zavezali, da bomo prinašali prvine zemlje svoje in prvine vsega sadu vsakovrstnih dreves leto za letom v hišo Gospodovo,',
        36: 'tudi prvence sinov svojih in živine svoje, kakor je pisano v postavi, in prvence govedi in drobnice svoje, da bomo vse prinašali v hišo Boga svojega, duhovnikom, ki strežejo v hiši Boga našega;',
        37: 'tudi da bomo prinašali prvine testa svojega in svoje dari povzdignjenja in sadove vsakovrstnih dreves, vino in olje, duhovnikom, v hrame pri hiši Boga svojega, desetino zemlje svoje pa levitom; zakaj oni, leviti, imajo dobivati desetine v vseh naših poljedeljskih mestih.',
        38: 'In duhovnik, sin Aronov, bodi pri levitih, ko bodo prejemali desetino. In leviti so dolžni prinesti desetino od desetin v hišo Boga našega, v shrambe pri zakladnici.',
        39: 'Kajti sinovi Izraelovi in sinovi Levijevi imajo prinašati dari povzdignjenja od žita, od vina in od olja v shrambe, kjer so posode svetišča in duhovniki, ki strežejo, vratarji in pevci. In nočemo zapustiti hiše Boga svojega.',
    },
    11: {
        1: 'In poglavarji ljudstva so prebivali v Jeruzalemu. In drugo ljudstvo je žrebalo, da se naroči enemu med desetimi, naj pride prebivat v Jeruzalem, sveto mesto, devet delov pa naj jih ostane v drugih mestih.',
        2: 'In ljudstvo je blagoslovilo vse može, ki so se rade volje ponudili, da bodo prebivali v Jeruzalemu.',
        3: 'Ti pa so prvaki pokrajine, ki so prebivali v Jeruzalemu; a po mestih Judovih so prebivali, vsak na svojem posestvu, v mestih svojih, Izraelci, duhovniki in leviti in Netinimci in sinovi hlapcev Salomonovih;',
        4: 'in v Jeruzalemu so prebivali nekateri sinov Judovih in sinov Benjaminovih. Iz sinov Judovih: Ataja, sin Uzija, sinu Zeharija, sinu Amarija, sinu Sefatija, sinu Mahalalela, od sinov Perezovih;',
        5: 'in Maaseja, sin Baruka, sinu Kolhozeja, sinu Hasaja, sinu Adaja, sinu Jojariba, sinu Zeharija, sinu Silonita.',
        6: 'Vseh sinov Perezovih, ki so prebivali v Jeruzalemu, je bilo štiristo oseminšestdeset junaških mož.',
        7: 'Ti pa so sinovi Benjaminovi: Salu, sin Mesulama, sinu Joeda, sinu Pedaja, sinu Kolaja, sinu Maaseja, sinu Itiela, sinu Jesaja.',
        8: 'In za njim Gabaj, Salaj, devetsto osemindvajset.',
        9: 'In Joel, sin Zihrijev, jim je bil nadzornik, in Juda, sin Hasenujev, je bil drugi nad mestom. –',
        10: 'Iz duhovnikov: Jedaja, sin Jojaribov, Jakin,',
        11: 'Seraja, sin Hilkija, sinu Mesulama, sinu Zadoka, sinu Merajota, sinu Ahituba, ta je bil poglavar hiše Božje;',
        12: 'in njih bratov, ki so opravljali delo v hiši, je bilo osemsto dvaindvajset; in Adaja, sin Jerohama, sinu Pelalija, sinu Amzija, sinu Zeharija, sinu Pashurja, sinu Malkija,',
        13: 'in njegovih bratov, poglavarjev očetovin, je bilo dvesto dvainštirideset; in Amasaj, sin Azarela, sinu Ahzaja, sinu Mesilemota, sinu Imerja,',
        14: 'in njih bratov, hrabrih junakov, sto osemindvajset. In nadzornik jim je bil Zabdiel, sin Hagedolimov.',
        15: 'In iz levitov: Semaja, sin Hašuba, sinu Azrikama, sinu Hasabija, sinu Bunija,',
        16: 'in Sabetaj in Jozabad, iz levitskih načelnikov, ki sta bila nad zunanjim delom pri hiši Božji;',
        17: 'in Matanija, sin Mika, sinu Zabdija, sinu Asafa, ki je bil vodja in je začenjal hvalopetje ob molitvi; in Bakbukija, drugi med svojimi brati, in Abda, sin Samua, sinu Galala, sinu Jedutuna.',
        18: 'Vseh levitov v svetem mestu je bilo dvesto štiriinosemdeset.',
        19: 'Dalje vratarji, Akub, Talmon in njiju bratov, ki so čuvali pri vratih, je bilo sto dvainsedemdeset.',
        20: 'Drugi Izraelci pa, duhovniki in leviti, so bili po vseh mestih Judovih, vsak na svojem posestvu.',
        21: 'A Netinimci so prebivali na Ofelu, in Ziha in Gispa sta bila nad Netinimci.',
        22: 'In v Jeruzalemu je bil nadzornik levitom Uzi, sin Banija, sinu Hasabija, sinu Matanija, sinu Mika, iz sinov Asafovih, pevcev za službo hiše Božje.',
        23: 'Kajti bila je zapoved kraljeva o njih in določen živež pevcem, kolikor je bilo vsak dan treba.',
        24: 'In Petahija, sin Mesezabelov, iz sinov Zeraha, sinu Judovega, je bil kralju pri roki v vsem, kar je zadevalo ljudstvo.',
        25: 'In po vaseh na svojem polju so prebivali nekateri sinov Judovih v Kirjat-arbi in njenih podložnih selih in v Dibonu in njemu podložnih vaseh in v Jekabzeelu in njemu podložnih vaseh,',
        26: 'in v Jesui in v Moladi in Betpeletu',
        27: 'in v Hazar-sualu in v Bersebi in njenih podložnih vaseh,',
        28: 'in v Ziklagu in v Mekoni in v njenih podložnih vaseh,',
        29: 'in v En-rimonu in v Zori in v Jarmutu,',
        30: 'v Zanoahu, v Adulamu in njemu podložnih vaseh, v Lahisu in na njegovem polju, v Azeki in njenih podložnih vaseh. In šatorili so od Bersebe do doline Hinomove.',
        31: 'Sinovi Benjaminovi so tudi prebivali od Gebe naprej v Mikmasu in v Aju in v Betelu in njegovih podložnih vaseh,',
        32: 'v Anatotu, Nobu, Ananiji,',
        33: 'Hazorju, Rami, Gitaimu,',
        34: 'Hadidu, Zeboimu, Nebalatu,',
        35: 'Lodu in v Onu, dolini obrtnikov.',
        36: 'In od levitov nekateri oddelki Judovi so se pridružili Benjaminu.',
    },
    12: {
        1: 'Ti pa so duhovniki in leviti, ki so šli gori z Zerubabelom, sinom Sealtielovim, in z Jesuom: Seraja, Jeremija, Ezra,',
        2: 'Amarija, Maluk, Hatuš,',
        3: 'Sekanija, Rehum, Meremot,',
        4: 'Ido, Ginetoj, Abija,',
        5: 'Mijamin, Maadija, Bilga,',
        6: 'Semaja, Jojarib, Jedaja,',
        7: 'Salu, Amok, Hilkija, Jedaja. Ti so bili poglavarji duhovnikov in njih bratov v dneh Jesujevih.',
        8: 'Dalje leviti: Jesua, Binuj, Kadmiel, Serebija, Juda in Matanija, ki je s svojimi brati vodil hvalopetje;',
        9: 'in Bakbukija in Uno, njih brata, sta jim bila nasproti, po svojih stražah.',
        10: 'In Jesua je rodil Jojakima, in Jojakim je rodil Eliasiba, Eliasib pa je rodil Jojada,',
        11: 'Jojada pa je rodil Jonatana, Jonatan pa je rodil Jadua.',
        12: 'In v dnevih Jojakima so bili duhovniki, poglavarji očetovin: Serajeve je bil Meraja, Jeremijeve: Hananija,',
        13: 'Ezrove: Mesulam, Amarijeve: Johanan,',
        14: 'Malukijeve: Jonatan; Sebanijeve: Jožef,',
        15: 'Harimove: Adna, Merajotove: Helkaj,',
        16: 'Idove: Zeharija, Ginetonove: Mesulam,',
        17: 'Abijeve: Zihri, Miniaminove... Moadijeve: Piltaj,',
        18: 'Bilgove: Samua, Semajeve: Jonatan,',
        19: 'Jojaribove: Matenaj, Jedajeve: Uzi,',
        20: 'Salajeve: Kalaj, Amokove: Heber,',
        21: 'Hilkijeve: Hasabija, Jedajeve: Netanel. –',
        22: 'V dneh Eliasiba, Jojada, Johanana in Jadua so bili zapisani poglavarji očetovin levitov in duhovnikov, ob vladanju Darija Peržana.',
        23: 'Sinovi Levijevi, poglavarji očetovin, so bili zapisani v knjigi letopisov, do dni Johanana, sinu Eliasibovega.',
        24: 'In poglavarji levitov: Hasabija, Serebija in Jesua (sin) Kadmiela in njih bratje, njim nasproti, da hvalijo in zahvaljujejo po zapovedi Davida, moža Božjega, službeni oddelki drug za drugim.',
        25: 'Matanija in Bakbukija, Obadija, Mesulam, Talmon, Akub so bili vratarji, stoječi na straži pri skladiščih ob vratih.',
        26: 'Ti so bili v dneh Jojakima, sinu Jesua, sinu Jozadaka, in v dneh Nehemija, deželnega oblastnika, in Ezra duhovnika, pismouka.',
        27: 'In ob posvečevanju obzidja jeruzalemskega so poiskali levite iz vseh njih mest, da bi jih pripeljali v Jeruzalem, da se praznuje posvečevanje z veseljem in z zahvaljevanjem in s petjem, s cimbali, s psalmovimi strunami in s harfami.',
        28: 'In sinovi pevcev so se zbrali iz vse okolice jeruzalemske in tudi iz netofatskih vasi',
        29: 'in iz Betgilgala in s poljan Gebe in Azmaveta; zakaj pevci so si zgradili sela okoli Jeruzalema.',
        30: 'In duhovniki in leviti so se očistili, in očistili so ljudstvo in vrata in obzidje.',
        31: 'In velel sem knezom Judovim stopiti na obzidje, in postavil sem dva velika zahvalna zbora in priredil obhod: eden je šel na desno, gori po obzidju, proti Gnojnim vratom.',
        32: 'In za njimi je šel Hosaja in polovica knezov Judovih,',
        33: 'in Azarija, Ezra, Mesulam,',
        34: 'Juda, Benjamin, Semaja in Jeremija,',
        35: 'in nekoliko duhovniških sinov s trobentami: Zeharija, sin Jonatana, sinu Semaja, sinu Matanija, sinu Mika, sinu Zakurija, sinu Asafa,',
        36: 'in bratje njegovi: Semaja, Azarel, Milalaj, Gilalaj, Maaj, Netanel, Juda, Hanani, z glasbili Davida, moža Božjega, in Ezra pismouk je bil pred njimi.',
        37: 'In šli so proti Studenčnim vratom, in so stopali naravnost naprej po stopnicah mesta Davidovega, koder se hodi gori na zid, zgoraj nad Davidovo hišo, prav do Vodnih vrat proti vzhodu.',
        38: 'Drugi zahvalni zbor pa jim je šel naproti, in jaz za njim s polovico ljudstva, vrhu obzidja, nad Pečnim stolpom ven do širokega zidu,',
        39: 'in nad Efraimovimi vrati in čez Stara vrata in čez Ribja vrata in stolp Hananel in stolp Mea tja do Ovčjih vrat, in obstali so pri vratih jetnišnice.',
        40: 'Tako sta stala obadva zahvalna zbora ob hiši Božji in jaz in polovica načelnikov ljudstva z menoj –',
        41: 'in duhovniki: Eliakim, Maaseja, Minjamin, Mihaja, Eljoenaj, Zeharija in Hananija s trobentami,',
        42: 'in Maaseja, Semaja, Eleazar, Uzi, Johanan, Malkija, Elam in Ezer. In pevci so glasno peli, in Jizrahija je bil njih vodja.',
        43: 'In tisti dan so darovali velike žrtve in se veselili; kajti Bog jih je obveselil z veliko radostjo, da so se tudi žene in otroci veselili. In jeruzalemsko veselje se je daleč slišalo.',
        44: 'V tistem času so bili možje postavljeni čez shrambe za zaklade, za dari povzdignjenja, za prvine in za desetine, da spravljajo vanje po obmestnih njivah, deleže, določene po postavi za duhovnike in levite; zakaj Juda se je veselil duhovnikov in levitov, ki so stali v službi.',
        45: 'In stregli so v straži Boga svojega in pazili na očiščevanje; enako tudi pevci in vratarji, po zapovedi Davida in Salomona, sinu njegovega.',
        46: 'Kajti nekdaj v dneh Davidovih in Asafovih, so bili načelniki pevcev in hvalopetja in zahvale Bogu.',
        47: 'In ves Izrael je v dneh Zerubabelovih in v dneh Nehemijevih dajal delež pevcem in vratarjem, kolikor je bilo treba vsak dan; in so del tega posvečevali levitom, in leviti so del posvečevali sinovom Aronovim.',
    },
    13: {
        1: 'Tisti čas se je čitalo pred ušesi ljudstva v knjigi Mojzesovi, in se je našlo pisano v njej, da ne sme Amonec in Moabec priti v zbor Božji vekomaj,',
        2: 'zato ker niso prišli naproti sinovom Izraelovim s kruhom in z vodo, temuč so zoper nje najeli Balaama, da bi jih proklel; toda naš Bog je kletev preobrnil v blagoslov.',
        3: 'In ko so slišali postavo, so ločili izmed Izraela vse mešano ljudstvo.',
        4: 'Pred tem pa je duhovnik Eliasib, ki je bil postavljen nad shrambami hiše našega Boga, ker je bil po rodu zvezan s Tobijem,',
        5: 'pripravil njemu veliko shrambo, kamor so bili poprej polagali jedilne daritve, kadilo in posode in desetine žita, vina in olja, po zapovedi pristojne levitom, pevcem in vratarjem, tudi dari povzdignjenja za duhovnike.',
        6: 'Ali ob vsem tem nisem bil v Jeruzalemu. Zakaj v dvaintridesetem letu Artakserksa, kralja babilonskega, sem šel h kralju; in čez nekoliko dni sem si izprosil dopust od kralja,',
        7: 'in ko sem dospel v Jeruzalem, sem opazil zlo, ki ga je bil storil Eliasib Tobiju na voljo s tem, da mu je pripravil shrambo na dvorišču hiše Božje.',
        8: 'In bilo mi je silno žal, in sem pometal vse stvari hiše Tobijeve iz shrambe.',
        9: 'Nato sem ukazal, in očistili so shrambe, in sem zopet vanje znosil posode hiše Božje, jedilne daritve in kadilo.',
        10: 'In zvedel sem, da niso dajali levitom njih deležev, in da so se zato umeknili leviti in pevci, ki so opravljali posel, vsak na svojo njivo.',
        11: 'Tedaj sem okaral načelnike in sem dejal: Zakaj je zapuščena hiša Božja? In sklical sem one ter jih postavil na njih mesto.',
        12: 'Tedaj je prinesel ves Juda desetino žita in vina in olja v založne shrambe.',
        13: 'In za paznike nad zalogami sem postavil Selemija duhovnika in Zadoka pismouka in izmed levitov Pedaja in njim v pomoč Hanana, sina Zakurja, sinu Matanija; zakaj oni so bili šteti za zveste, in bilo jim je poverjeno, da delijo svojim bratom.',
        14: 'Spominjaj se mi tega, o Bog moj, in ne izbriši mojih del usmiljenja, ki sem jih storil pri Boga svojega hiši in za postrežbo pri njej.',
        15: 'Tisti čas sem videl v Judeji, da so nekateri ob soboti tlačili tlačilnice in spravljali snopovje in ž njimi obkladali osle, pa tudi z vinom, z grozdjem in s smokvami in z vsakršnimi tovori, ki so jih prinašali v Jeruzalem ob sobotnem dnevi. In posvaril sem jih tisti dan, ko so prodajali živež.',
        16: 'Tudi so prebivali v mestu Tirci, ki so prinašali ribe in različno blago ter prodajali ob sobotah sinovom Judovim in v Jeruzalemu.',
        17: 'Tedaj sem okaral plemenitnike Judove in jim dejal: Kakšna je to huda razvada, ki jo imate, da oskrunjate sobotni dan?',
        18: 'Niso li vaši očetje delali tudi tako, in ni li spravil Bog naš vseh teh nesreč nad nas in nad to mesto? In vi pripravljate še več srda nad Izraela s tem, da oskrunjate soboto!',
        19: 'In ko se je začelo mračiti med vrati Jeruzalema pred soboto, velel sem, naj zapro duri, in naročil, da jih smejo odpreti šele po soboti; in nekatere svoje hlapce sem postavil, da bi se ne prinesla nobena butara v mesto ob sobotnem dnevi.',
        20: 'Tedaj so kramarji in prodajalci raznovrstnega blaga ostali čez noč zunaj pred Jeruzalemom, enkrat ali dvakrat.',
        21: 'In okaral sem jih in jim dejal: Zakaj ostajate čez noč okoli obzidja? Ako še enkrat to storite, položim na vas roko! Od tega časa niso več prišli v soboto.',
        22: 'In ukazal sem levitom, naj se očistijo in pridejo stražit vrata, da bi se sobotni dan posvečeval. Tudi tega se mi spominjaj, o Bog moj, in prizanesi mi po veliki milosti svoji!',
        23: 'Tudi sem videl v tistem času Jude, ki so se poročili z ženami iz Asdoda, Amona in Moaba;',
        24: 'in njih otroci so polovico govorili asdotski in niso znali po judovsko, temuč govorili so po jeziku tega ali onega ljudstva.',
        25: 'In sem jih karal in klel ter nekatere izmed njih sem tepel in jim ruval lase, in velel sem jim priseči pri Bogu, da ne bodo dajali hčer svojih njih sinovom, ne jemali njih hčer sinom svojim ali sami sebi.',
        26: 'Ni li grešil zaradi tujk Salomon, kralj Izraelov? In vendar mu ni bilo med mnogimi narodi enakega kralja, in ljub je bil svojemu Bogu, in Bog ga je postavil za kralja vsemu Izraelu: a celo njega so zapeljale tuje žene v greh!',
        27: 'In naj li poslušamo vas, ki delate tako veliko zlo in nezvesto ravnate zoper Boga svojega, ko se poročate z drugorodnimi ženami?',
        28: 'In eden izmed sinov Jojada, sinu Eliasibovega, velikega duhovnika se je bil posvačil s Sanbalatom Horončanom; zato sem ga odgnal od sebe.',
        29: 'Spominjaj se jih, o Bog moj, da so onečistili duhovništvo in zavezo duhovništva in levitov!',
        30: 'Tako sem jih očistil vsega tujega in postavil službena opravila duhovnikov in levitov, vsakega k svojemu poslu,',
        31: 'in sem oskrbel, da se prinašajo drva ob določenih časih in prvine. Spominjaj se me, o Bog moj, meni v dobro!',
    },
}
